<section><div class="page-heading"><div><a class="back-link" href="/sa/merchants">← Merchants</a><p class="eyebrow">Merchant account</p><h1><?= e($merchant['name']) ?></h1><p class="muted"><?= e($merchant['email']) ?> · Joined <?= e($merchant['created_at']) ?></p></div><span class="badge <?= strtolower($merchant['status']) ?>"><?= e($merchant['status']) ?></span></div><div class="admin-detail-grid"><section class="panel"><div class="panel-title"><h2>Account</h2><span>No password data shown</span></div><dl class="admin-definition"><div><dt>Email verified</dt><dd><?= $merchant['email_verified_at']?e($merchant['email_verified_at']):'No' ?></dd></div><div><dt>Last login</dt><dd><?= e($merchant['last_login_at']??'Never') ?></dd></div><div><dt>Password changed</dt><dd><?= e($merchant['password_changed_at']??'Never') ?></dd></div></dl><form method="post" action="/sa/merchants/<?= e($merchant['id']) ?>/status" data-confirm="<?= $merchant['status']==='ACTIVE'?'Suspend merchant access?':'Reactivate merchant access?' ?>" data-confirm-message="This changes login access. Store publication is managed separately."><?= csrf_field() ?><input type="hidden" name="status" value="<?= $merchant['status']==='ACTIVE'?'SUSPENDED':'ACTIVE' ?>"><button class="button <?= $merchant['status']==='ACTIVE'?'danger':'primary' ?>" type="submit"><?= $merchant['status']==='ACTIVE'?'Suspend merchant':'Reactivate merchant' ?></button></form></section><section class="panel"><div class="panel-title"><h2>Recent audit activity</h2><span><?= count($audit) ?> entries</span></div><?php if(!$audit):?><div class="empty-inline">No account activity recorded.</div><?php else:?><div class="event-list"><?php foreach($audit as$row):?><div><strong><?= e($row['event']) ?></strong><small><?= e(($row['target_type']??'system').' #'.($row['target_id']??'—')) ?> · <?= e($row['created_at']) ?></small></div><?php endforeach ?></div><?php endif ?></section></div><section class="panel flush"><div class="list-head"><span>Stores and subscriptions</span><small><?= count($stores) ?> memberships</small></div><?php if(!$stores):?><div class="empty-inline padded">This merchant has no stores.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Store</th><th>Role</th><th>Status</th><th>Plan</th><th>Usage</th><th></th></tr></thead><tbody><?php foreach($stores as$row):?><tr><td><strong><?= e($row['name']) ?></strong><small>/<?= e($row['slug']) ?></small></td><td><?= e($row['role']) ?></td><td><span class="badge <?= strtolower($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= e($row['plan_name']??'Unconfigured') ?><small><?= e($row['subscription_status']??'') ?></small></td><td><?= e($row['products']) ?> products · <?= e($row['categories']) ?> categories<small><?= e($row['staff']) ?> staff · <?= e($row['orders']) ?> orders</small></td><td><a class="button compact secondary" href="/sa/stores/<?= e($row['id']) ?>">Inspect</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section></section>
